grader.tests:
assert env_lines(' # hi\n A=x=y\nB=\nA=z # literal')=={'A':'z # literal','B':''}
assert env_lines('Q="hello"')=={'Q':'"hello"'}
assert env_lines('')=={}
for text in ['=x','NO_EQUALS']:
    try: env_lines(text)
    except ValueError: pass
    else: raise AssertionError('invalid accepted')

a={'a':1,'b':2,'d':None}; b={'a':1,'b':3,'c':4}
assert reconcile(a,b)=={'create':['d'],'update':['b'],'delete':['c']}
assert a=={'a':1,'b':2,'d':None}
assert reconcile({},{})=={'create':[],'update':[],'delete':[]}

assert delays(1,2,8)==[]
assert delays(6,2,7)==[2,4,7,7,7]
assert delays(3,0,8)==[0,0]
assert delays(3,4,0)==[0,0]
for a,b,c in [(0,1,1),(1,-1,1),(1,1,-1)]:
    try: delays(a,b,c)
    except ValueError: pass
    else: raise AssertionError('invalid accepted')

a={'x':('a',3),'y':('b',None),'z':('c',4)}
assert live(a,3)=={'y':('b',None),'z':('c',4)}
assert len(a)==3
assert live({},0)=={}
assert live(a,2)==a
assert live(a,2) is not a

assert histogram([0,1,2],[-1,0,0.5,1,2,3])==[2,2]
assert histogram([0,10],[])==[0]
for edges in [[],[0],[0,0],[2,1]]:
    try: histogram(edges,[])
    except ValueError: pass
    else: raise AssertionError('invalid edges')

a={'db':{'port':1,'hosts':['a']},'x':3}
b={'db':{'port':2},'x':None}
r=merge(a,b)
assert r=={'db':{'port':2,'hosts':['a']},'x':None}
r['db']['hosts'].append('z')
assert a['db']['hosts']==['a']
assert b=={'db':{'port':2},'x':None}
assert merge({'a':[1]},{'a':[2]})=={'a':[2]}

assert parse_jsonl('  
{"a":1}
null
[2]
')==[{'a':1},None,[2]]
assert parse_jsonl('')==[]
try: parse_jsonl('{}

INVALID')
except ValueError as e: assert '3' in str(e)
else: raise AssertionError('invalid JSON accepted')

assert flatten({})=={}
assert flatten({'a':{'b':1,'c':{}},'d':[1,2],'e':None})=={'a.b':1,'a.c':{},'d':[1,2],'e':None}
a={'x':{'y':2}}
assert flatten(a)=={'x.y':2} and a=={'x':{'y':2}}

assert normalize('/a//b/../c/.')=='/a/c'
assert normalize('/../../')=='/'
assert normalize('/a/.../')=='/a/...'
for p in ['', 'a/b']:
    try: normalize(p)
    except ValueError: pass
    else: raise AssertionError('relative accepted')

assert pack(['é','a','b'],3)==[['é','a'],['b']]
assert pack(['abc','','x'],3)==[['abc',''],['x']]
assert pack([],1)==[]
assert pack(['',''],1)==[['','']]
for items,n in [(['é'],1),([],0)]:
    try: pack(items,n)
    except ValueError: pass
    else: raise AssertionError('oversize accepted')

assert admit([0,0,1,5,5,6],2,5)==[True,True,False,True,True,False]
assert admit([0,4,5],1,5)==[True,False,True]
assert admit([],1,1)==[]
for limit,w in [(0,1),(1,0)]:
    try: admit([],limit,w)
    except ValueError: pass
    else: raise AssertionError('invalid accepted')

assert order({})==[]
assert order({'b':['a'],'d':['b'],'c':[]})==['a','b','c','d']
a={'b':['a','a']}
assert order(a)==['a','b'] and a=={'b':['a','a']}
for d in ({'x':['x']},{'a':['b'],'b':['a']}):
    try: order(d)
    except ValueError: pass
    else: raise AssertionError('cycle accepted')

